package main

import (
	"html"
	"html/template"
)

// presetLogo is the logo of an online tool's preset, or its letter mark.
func presetLogo(id string) template.HTML {
	if d, ok := presetLogos[id]; ok {
		return template.HTML(`<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="` + html.EscapeString(d) + `"/></svg>`)
	}
	p, ok := presetByID(id)
	if !ok || p.Mark == "" {
		return ""
	}
	size, y := "15", "17.3"
	if len([]rune(p.Mark)) > 1 {
		size, y = "11", "16"
	}
	return template.HTML(`<svg viewBox="0 0 24 24" aria-hidden="true"><text x="12" y="` + y + `" text-anchor="middle" ` +
		`font-family="system-ui, -apple-system, sans-serif" font-size="` + size + `" font-weight="800" fill="currentColor">` +
		html.EscapeString(p.Mark) + `</text></svg>`)
}

